-- Structure for view `v_stock_onhand`
--
DROP TABLE IF EXISTS `v_stock_onhand`;

CREATE ALGORITHM=UNDEFINED DEFINER=`binsult1_vahla`@`localhost` SQL SECURITY DEFINER VIEW `v_stock_onhand`  AS SELECT `stock_movements`.`product_id` AS `product_id`, round(coalesce(sum((case when (`stock_movements`.`type` in ('in','assembly_in')) then abs(`stock_movements`.`qty`) when (`stock_movements`.`type` in ('out','assembly_out')) then -(abs(`stock_movements`.`qty`)) when (`stock_movements`.`type` = 'adjustment') then `stock_movements`.`qty` else 0 end)),0),3) AS `onhand_qty` FROM `stock_movements` GROUP BY `stock_movements`.`product_id` ;

